  "connectors/whatsapp_business.rk": {
   "path": "connectors/whatsapp_business.rk",
   "kind": "connector",
   "layer": 3,
   "text": "# yaml-language-server: $schema=https://rangka-os.github.io/rangka-os/schema/0.4/connector.json\nname: whatsapp_business\nlabel: {id: WhatsApp Business}\nversion: 1.0.0\nvendor: Meta WhatsApp Cloud API\ndocs: https://developers.facebook.com/docs/whatsapp/cloud-api\nauth:\n  type: token\n  fields:\n    - name: access_token\n      label: {id: Access token}\n      secret: true\n    - name: phone_number_id\n      label: {id: Phone number ID}\n    - name: app_secret\n      label: {id: App secret}\n      secret: true\n      help: {id: Dipakai untuk memeriksa tanda tangan webhook}\n    - name: verify_token\n      label: {id: Verify token}\n      secret: true\n      generate: true\ntriggers:\n  - name: message_received\n    label: {id: Pesan masuk}\n    via: webhook\n    verify:\n      challenge: hub.verify_token == auth.verify_token\n      signature:\n        header: X-Hub-Signature-256\n        alg: hmac-sha256\n        key: auth.app_secret\n    for_each: entry[].changes[].value.messages[]\n    emit:\n      message_id: item.id\n      from: item.from\n      text: item.text.body\n      profile_name: value.contacts[0].profile.name\n      at: item.timestamp\nactions:\n  - name: send_template\n    label: {id: Kirim pesan template}\n    request:\n      method: POST\n      url: https://graph.facebook.com/{api_version}/{auth.phone_number_id}/messages\n      headers: {Authorization: 'Bearer {auth.access_token}'}\n      body:\n        messaging_product: whatsapp\n        to: '{input.to}'\n        type: template\n        template:\n          name: '{input.template}'\n          language: {code: id}\n          components: '{input.components}'\n    input:\n      - {name: to, type: phone, required: true}\n      - {name: template, type: data, required: true}\n      - {name: components, type: json}\n    retry:\n      max: 5\n      backoff: exponential\n      on: [429, 500, 502, 503]\n    idempotency: input.idempotency_key\nsettings:\n  - {name: api_version, type: data, default: \"'v21.0'\"}\nlimits:\n  rate: 80/s per phone number\n  note: {id: Pesan template di luar jendela 24 jam dikenai biaya oleh Meta}\n",
   "parsed": {
    "name": "whatsapp_business",
    "label": {
     "id": "WhatsApp Business"
    },
    "version": "1.0.0",
    "vendor": "Meta WhatsApp Cloud API",
    "docs": "https://developers.facebook.com/docs/whatsapp/cloud-api",
    "auth": {
     "type": "token",
     "fields": [
      {
       "name": "access_token",
       "label": {
        "id": "Access token"
       },
       "secret": true
      },
      {
       "name": "phone_number_id",
       "label": {
        "id": "Phone number ID"
       }
      },
      {
       "name": "app_secret",
       "label": {
        "id": "App secret"
       },
       "secret": true,
       "help": {
        "id": "Dipakai untuk memeriksa tanda tangan webhook"
       }
      },
      {
       "name": "verify_token",
       "label": {
        "id": "Verify token"
       },
       "secret": true,
       "generate": true
      }
     ]
    },
    "triggers": [
     {
      "name": "message_received",
      "label": {
       "id": "Pesan masuk"
      },
      "via": "webhook",
      "verify": {
       "challenge": "hub.verify_token == auth.verify_token",
       "signature": {
        "header": "X-Hub-Signature-256",
        "alg": "hmac-sha256",
        "key": "auth.app_secret"
       }
      },
      "for_each": "entry[].changes[].value.messages[]",
      "emit": {
       "message_id": "item.id",
       "from": "item.from",
       "text": "item.text.body",
       "profile_name": "value.contacts[0].profile.name",
       "at": "item.timestamp"
      }
     }
    ],
    "actions": [
     {
      "name": "send_template",
      "label": {
       "id": "Kirim pesan template"
      },
      "request": {
       "method": "POST",
       "url": "https://graph.facebook.com/{api_version}/{auth.phone_number_id}/messages",
       "headers": {
        "Authorization": "Bearer {auth.access_token}"
       },
       "body": {
        "messaging_product": "whatsapp",
        "to": "{input.to}",
        "type": "template",
        "template": {
         "name": "{input.template}",
         "language": {
          "code": "id"
         },
         "components": "{input.components}"
        }
       }
      },
      "input": [
       {
        "name": "to",
        "type": "phone",
        "required": true
       },
       {
        "name": "template",
        "type": "data",
        "required": true
       },
       {
        "name": "components",
        "type": "json"
       }
      ],
      "retry": {
       "max": 5,
       "backoff": "exponential",
       "on": [
        429,
        500,
        502,
        503
       ]
      },
      "idempotency": "input.idempotency_key"
     }
    ],
    "settings": [
     {
      "name": "api_version",
      "type": "data",
      "default": "'v21.0'"
     }
    ],
    "limits": {
     "rate": "80/s per phone number",
     "note": {
      "id": "Pesan template di luar jendela 24 jam dikenai biaya oleh Meta"
     }
    }
   },
   "lines": 68,
   "sha": "3a837cd553b2c62e",
   "source": "rangka-connectors/whatsapp_business/connector.rk"
  },
